var style=document.createElement('style');style.id='orkida-header-v5-css';style.textContent="\n#orkida-product-nav{position:sticky;top:0;z-index:40;background:white;border-bottom:1px solid #eee9f3;color:#332c39;font-family:inherit;direction:rtl}\n#orkida-product-nav[hidden]{display:none!important}\n#orkida-product-nav *{box-sizing:border-box}\n#orkida-product-nav .on-bar{height:76px;max-width:1160px;padding:0 16px;margin:auto;display:grid;grid-template-columns:1fr 112px 1fr;align-items:center}\n#orkida-product-nav button{border:0;background:none;color:inherit;cursor:pointer;font:inherit;padding:0}\n#orkida-product-nav .on-btn{width:44px;height:44px;display:inline-flex;align-items:center;justify-content:center;border-radius:50%;flex-shrink:0}\n#orkida-product-nav .on-btn:hover{background:#f4eef9;color:#5f1ea4}\n#orkida-product-nav svg{width:25px;height:25px;display:block;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}\n#orkida-product-nav .on-actions{display:flex;direction:ltr;justify-content:flex-start;gap:3px}\n#orkida-product-nav .on-logo{position:relative;display:block;width:112px;height:70px;overflow:hidden}\n#orkida-product-nav .on-logo img{position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:132px!important;height:132px!important;max-width:none!important;object-fit:contain}\n#orkida-product-nav .on-menu{justify-self:start}\n#orkida-product-nav a:focus-visible,#orkida-product-nav button:focus-visible{outline:3px solid #9e6bcb;outline-offset:2px}\n#orkida-product-nav dialog{position:fixed;inset:0 0 0 auto;margin:0;width:min(85vw,350px);height:100%;height:100dvh;max-height:none;max-width:none;border:0;padding:0;background:#fff;color:#332c39;direction:rtl;box-shadow:-8px 0 30px #24133422}\n#orkida-product-nav dialog::backdrop{background:rgba(24,14,32,.38)}\n#orkida-product-nav .on-panel-head{height:88px;display:flex;align-items:center;justify-content:space-between;padding:8px 20px;background:#faf8fc;border-bottom:1px solid #eee9f3}\n#orkida-product-nav .on-panel-head h2{font-size:18px;margin:0;color:#5f1ea4}\n#orkida-product-nav .on-section{padding:20px;overflow:auto;max-height:calc(100dvh - 88px)}\n#orkida-product-nav .on-section a{display:flex;align-items:center;gap:14px;min-height:54px;padding:12px 10px;text-decoration:none;color:#51405f;font-size:15px;border-bottom:1px solid #f2edf6}\n#orkida-product-nav .on-section a:hover{background:#f7f2fc;color:#5f1ea4}\n#orkida-product-nav .on-section a:first-child{font-weight:700;color:#5f1ea4}\n#orkida-product-nav .on-section svg{width:21px;height:21px;flex-shrink:0}\n@media(min-width:961px){#orkida-product-nav .on-bar{height:84px}#orkida-product-nav .on-actions{gap:10px}}\n@media(prefers-reduced-motion:no-preference){#orkida-product-nav dialog[open]{animation:on-enter .2s ease-out}@keyframes on-enter{from{transform:translateX(100%)}to{transform:translateX(0)}}}\n";document.head.appendChild(style);
