var d=nav.querySelector('dialog'),trigger=nav.querySelector('.on-menu');
trigger.onclick=function(){oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';d.showModal();trigger.setAttribute('aria-expanded','true');};
