d.addEventListener('click',function(e){var r=d.getBoundingClientRect();if(e.target.closest('a')||(e.target===d&&(e.clientX<r.left||e.clientX>r.right)))d.close();});
d.addEventListener('close',function(){document.body.style.overflow=oldOverflow;trigger.setAttribute('aria-expanded','false');trigger.focus();});
